export type CategoryType = 'subject' | 'scene' | 'style';

export interface ImageVariant {
  url: string;
  mediaId: string;
  prompt: string;
}

export interface CategoryImage {
  id: string;
  mediaId?: string;
  url?: string;
  active: boolean;
  loading?: boolean;
  prompt?: string;
  sourceIndex?: number;
  variants?: ImageVariant[];
}

export interface CategoryData {
  id: CategoryType;
  title: string;
  description: string;
  images: CategoryImage[];
  poolOrder: number[]; // Shuffled indices for the session
  currentOrderIndex: number; // Current position in the shuffled pool
}

export interface AppState {
  subject: CategoryData;
  scene: CategoryData;
  style: CategoryData;
}

import React from 'react';
import { Loader2, Check, Trash2, Pencil } from 'lucide-react';
import { CategoryData } from '../types';

interface CategoryCardProps {
  data: CategoryData;
  onToggleActive: (imageId: string) => void;
  onRemoveImage: (imageId: string) => void;
  onEditImage: (imageId: string) => void;
  onUpload?: (targetId: string) => void;
  onGenerate?: (targetId: string) => void;
}

export const getCategoryIcon = (id: string) => {
  switch (id) {
    case 'subject': return 'person';
    case 'scene': return 'location_on';
    case 'style': return 'stylus_note';
    default: return 'add_circle';
  }
};

export const CategoryCard: React.FC<CategoryCardProps> = ({ 
  data, 
  onToggleActive,
  onRemoveImage,
  onEditImage,
  onUpload,
  onGenerate
}) => {
  return (
    <div className="space-y-4 w-full flex flex-col items-center">
      <div className="flex flex-col items-center gap-4 w-full">
        {data.images.map((img) => (
          <div key={img.id} className="relative w-full flex justify-center">
            {img.loading ? (
              <div className="relative w-full max-w-[220px] aspect-square rounded-2xl flex items-center justify-center border-2 border-dashed border-black/10 bg-transparent group">
                <Loader2 className="w-8 h-8 animate-spin text-black" />

                {/* Cancel/Delete while loading */}
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    onRemoveImage(img.id);
                  }}
                  className="absolute top-2 right-2 p-1.5 bg-black/5 rounded-lg text-black/40 opacity-0 group-hover:opacity-100 transition-all hover:bg-[#000000] hover:text-white flex items-center justify-center cursor-pointer"
                  title="Cancel Generation"
                >
                  <Trash2 className="w-3.5 h-3.5" />
                </button>
              </div>
            ) : img.url ? (
              <div 
                className={`group relative w-full max-w-[220px] aspect-square rounded-2xl overflow-hidden border-2 transition-all cursor-pointer ${img.active ? 'border-black scale-[0.98]' : 'border-transparent opacity-60 hover:opacity-100'}`}
                onClick={() => onToggleActive(img.id)}
              >
                <img 
                  src={img.url} 
                  alt="Ingredient" 
                  className="w-full h-full object-cover"
                />

                {img.active && (
                  <div className="absolute top-2 right-2 z-10">
                    <div className="w-6 h-6 bg-[#F5D547] rounded-full flex items-center justify-center border border-black">
                       <Check className="w-4 h-4 text-black" strokeWidth={4} />
                    </div>
                  </div>
                )}

                {/* Edit Icon */}
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    onEditImage(img.id);
                  }}
                  className="absolute bottom-2 left-2 p-2 bg-black/60 rounded-xl text-white opacity-0 group-hover:opacity-100 transition-all hover:bg-[#000000] hover:scale-110 flex items-center justify-center"
                  title="View Description"
                >
                  <Pencil className="w-4 h-4 text-white" />
                </button>

                {/* Remove Action */}
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    onRemoveImage(img.id);
                  }}
                  className="absolute bottom-2 right-2 p-2 bg-black/60 rounded-xl text-white opacity-0 group-hover:opacity-100 transition-all hover:bg-[#000000] hover:scale-110 flex items-center justify-center"
                >
                  <Trash2 className="w-4 h-4 text-white" />
                </button>
              </div>
            ) : (
              <div 
                className="w-full max-w-[220px] aspect-square rounded-2xl border-[2px] border-dashed border-[rgba(27,27,27,0.5)] relative overflow-hidden group transition-all hover:border-black/40 bg-transparent"
              >
                <div className="absolute inset-0 flex flex-col items-center justify-center transition-opacity duration-200 group-hover:opacity-0 pointer-events-none">
                  <span className="material-symbols-outlined text-[52px] text-black">
                    {getCategoryIcon(data.id)}
                  </span>
                </div>

                <div className="absolute inset-0 flex flex-col items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity duration-200">
                  <button 
                    onClick={() => onGenerate?.(img.id)}
                    className="flex-1 w-full flex items-center justify-center hover:bg-black/[0.03] transition-colors"
                  >
                    <span className="material-symbols-outlined text-[20px] text-black">edit</span>
                  </button>
                  <div className="h-[0.8px] w-12 bg-black/10" />
                  <button 
                    onClick={() => onUpload?.(img.id)}
                    className="flex-1 w-full flex items-center justify-center hover:bg-black/[0.03] transition-colors"
                  >
                    <span className="material-symbols-outlined text-[20px] text-black">image</span>
                  </button>
                </div>

                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    onRemoveImage(img.id);
                  }}
                  className="absolute top-2 right-2 p-1.5 bg-black/5 rounded-lg text-black/40 opacity-0 group-hover:opacity-100 transition-all hover:bg-[#000000] hover:text-white flex items-center justify-center"
                >
                  <Trash2 className="w-3.5 h-3.5" />
                </button>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { X, Loader2 } from 'lucide-react';

interface GenerationModalProps {
  isOpen: boolean;
  onClose: () => void;
  onGenerate: (prompt: string) => Promise<void>;
  onUpload: () => void;
  title: string;
  initialView?: 'choice' | 'prompt';
}

export const GenerationModal: React.FC<GenerationModalProps> = ({ 
  isOpen, 
  onClose, 
  onGenerate, 
  onUpload,
  title,
  initialView = 'choice'
}) => {
  const [view, setView] = useState<'choice' | 'prompt'>(initialView);
  const [prompt, setPrompt] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Reset view when opening
  useEffect(() => {
    if (isOpen) {
      setView(initialView);
      setPrompt('');
      setIsSubmitting(false);
    }
  }, [isOpen, initialView]);

  if (!isOpen) return null;

  const handleGenerateClick = () => {
    if (!prompt.trim() || isSubmitting) return;
    setIsSubmitting(true);
    onGenerate(prompt).catch(err => {
      console.error("Background Generation Error:", err);
    });
    onClose();
  };

  const handleClose = () => {
    if (isSubmitting) return;
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm">
      <div className="w-full max-w-4xl bg-[#F5D547] rounded-2xl shadow-2xl overflow-hidden relative border border-black/10 flex h-[600px] animate-in fade-in zoom-in duration-200">
        <h2 className="whisk-dialog-title">Generate a {title}</h2>

        <button 
          onClick={handleClose} 
          disabled={isSubmitting}
          className="absolute top-6 right-6 p-2 rounded-full hover:bg-black/5 text-black transition-colors z-10 disabled:opacity-20"
        >
          <X className="w-5 h-5 text-black" />
        </button>

        {view === 'choice' ? (
          <div className="flex w-full h-full pt-16">
            <button 
              onClick={() => setView('prompt')}
              className="flex-1 flex flex-col items-center justify-center gap-4 group transition-all hover:bg-black/5 p-8"
            >
              <div className="w-16 h-16 rounded-full bg-black/10 flex items-center justify-center group-hover:scale-110 transition-transform">
                <span className="material-symbols-outlined text-[16px] text-black">stylus_note</span>
              </div>
              <span className="text-xs font-black uppercase tracking-[0.3em] text-black">Generate with Text</span>
            </button>

            <div className="w-px bg-black/10 my-10" />

            <button 
              onClick={() => {
                onUpload();
                onClose();
              }}
              className="flex-1 flex flex-col items-center justify-center gap-4 group transition-all hover:bg-black/5 p-8"
            >
              <div className="w-16 h-16 rounded-full bg-black/10 flex items-center justify-center group-hover:scale-110 transition-transform">
                <span className="material-symbols-outlined text-[16px] text-black">image</span>
              </div>
              <span className="text-xs font-black uppercase tracking-[0.3em] text-black">Select from Gallery</span>
            </button>
          </div>
        ) : (
          <div className="flex-1 flex flex-col relative p-10 pt-24 h-full">
             <div className="flex-1 flex flex-col gap-6 min-h-0">
                <div className="flex-1 bg-black/5 rounded-[2rem] p-8 flex flex-col">
                  <label className="block text-[10px] font-black uppercase tracking-[0.2em] text-black mb-4">
                    Prompt
                  </label>
                  <textarea
                    autoFocus
                    disabled={isSubmitting}
                    value={prompt}
                    onChange={(e) => setPrompt(e.target.value)}
                    placeholder={`Describe your ${title.toLowerCase()}...`}
                    className="flex-1 w-full bg-transparent border-none text-sm text-black leading-relaxed font-medium focus:ring-0 focus:outline-none resize-none scrollbar-hide"
                  />
                </div>
                <div className="flex items-center justify-center pt-2">
                  <button
                    type="button"
                    onClick={handleGenerateClick}
                    disabled={!prompt.trim() || isSubmitting}
                    className="px-16 py-4 rounded-full bg-black text-white text-[10px] font-black uppercase tracking-[0.2em] hover:bg-zinc-900 transition-all active:scale-95 shadow-xl flex items-center gap-3 disabled:opacity-30"
                  >
                    <span>{isSubmitting ? 'Generating...' : 'Generate'}</span>
                    {isSubmitting ? (
                      <Loader2 className="w-4 h-4 animate-spin" />
                    ) : (
                      <span className="material-symbols-outlined text-[20px]">arrow_forward</span>
                    )}
                  </button>
                </div>
             </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Flow } from 'flow-sdk';
import { Download, Trash2, Loader2, ChevronLeft, ChevronRight, AlertCircle, X, Menu } from 'lucide-react';
import { CategoryCard, getCategoryIcon } from './components/CategoryCard';
import { GenerationModal } from './components/GenerationModal';
import { InfoModal } from './components/InfoModal';
import { ResultViewModal } from './components/ResultViewModal';
import { aiService, POOL_LENGTHS } from './services/aiService';
import { AppState, CategoryType } from './types';

/** Helper to shuffle an array of numbers */
function shuffleIndices(count: number): number[] {
  const arr = Array.from({ length: Math.max(0, count) }, (_, i) => i);
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

const INITIAL_STATE: AppState = {
  subject: { 
    id: 'subject', title: 'Subject', description: 'What is it?', 
    images: [{ id: 'init-sub', active: true, sourceIndex: -1 }], 
    poolOrder: shuffleIndices(POOL_LENGTHS.subject), 
    currentOrderIndex: 0 
  },
  scene: { 
    id: 'scene', title: 'Scene', description: 'Where is it?', 
    images: [{ id: 'init-scene', active: true, sourceIndex: -1 }], 
    poolOrder: shuffleIndices(POOL_LENGTHS.scene), 
    currentOrderIndex: 0 
  },
  style: { 
    id: 'style', title: 'Style', description: 'How does it look?', 
    images: [{ id: 'init-style', active: true, sourceIndex: -1 }], 
    poolOrder: shuffleIndices(POOL_LENGTHS.style), 
    currentOrderIndex: 0 
  },
};

/** Sanitize a filename for safe download usage. */
function sanitizeFilename(name: string, index: number, mimeType: string): string {
  const ext = mimeType.split('/')[1]?.replace('jpeg', 'jpg') || 'png';
  const clean = name
    .replace(/[^a-zA-Z0-9_\-]/g, '_')
    .replace(/_+/g, '_')
    .slice(0, 30);
  return `${clean || 'whisk_creation'}_${index + 1}.${ext}`;
}

export default function App() {
  const [state, setState] = useState<AppState>(INITIAL_STATE);
  const [modalMode, setModalMode] = useState<{ type: CategoryType; isOpen: boolean; initialView?: 'choice' | 'prompt'; targetId?: string } | null>(null);
  const [infoModal, setInfoModal] = useState<{ isOpen: boolean; type: CategoryType; imageId: string; title: string; description: string | null; isLoading: boolean; isGenerating: boolean } | null>(null);
  const [expandedResult, setExpandedResult] = useState<any | null>(null);
  const [activeResults, setActiveResults] = useState<any[]>([]);
  const [whiskPrompt, setWhiskPrompt] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [sidebarOpen, setSidebarOpen] = useState(window.innerWidth > 1024);
  const [globalLoading, setGlobalLoading] = useState<Record<string, boolean>>({});
  const [gridCols, setGridCols] = useState(2);

  useEffect(() => {
    const fontIds = ['gfont-preconnect-1', 'gfont-link', 'gfont-icons'];
    if (!document.getElementById(fontIds[0])) {
      const link = document.createElement('link');
      link.id = fontIds[1]; link.rel = 'stylesheet';
      link.href = 'https://fonts.googleapis.com/css2?family=Google+Sans:wght@300;400;500;700&family=Google+Sans+Text:wght@300;400;500;700&family=Google+Sans+Mono:wght@300;400;700&display=swap';
      const icons = document.createElement('link');
      icons.id = fontIds[2]; icons.rel = 'stylesheet';
      icons.href = 'https://fonts.googleapis.com/css2?family=Material+Symbols+Outlined:opsz,wght,FILL,GRAD@20..48,400,0,0';
      document.head.append(link, icons);
    }
    const styleId = 'whisk-styles';
    if (!document.getElementById(styleId)) {
      const style = document.createElement('style'); style.id = styleId;
      style.textContent = `
        html, body, #root { margin: 0; padding: 0; width: 100%; height: 100%; font-family: 'Google Sans Text', sans-serif !important; letter-spacing: 0.1px; background: #DDE2E5; } 
        .scrollbar-hide::-webkit-scrollbar { display: none; } 
        @keyframes spin-dice { from { transform: rotate(0deg); } to { transform: rotate(360deg); } } 
        .animate-dice { animation: spin-dice 0.6s ease-in-out; }
        @keyframes shimmer { 0% { background-position: -200% 0; } 100% { background-position: 200% 0; } }
        .whisk-shimmer {
          background: linear-gradient(110deg, rgba(220, 220, 220, 0.2) 20%, rgba(220, 220, 220, 0.5) 50%, rgba(220, 220, 220, 0.2) 80%);
          background-size: 200% 100%;
          animation: shimmer 2s infinite;
        }
        input[type=range].size-slider {
          -webkit-appearance: none;
          background: transparent;
        }
        input[type=range].size-slider::-webkit-slider-runnable-track {
          width: 100%;
          height: 4px;
          background: rgba(0,0,0,0.1);
          border-radius: 2px;
        }
        input[type=range].size-slider::-webkit-slider-thumb {
          -webkit-appearance: none;
          height: 12px;
          width: 12px;
          border-radius: 50%;
          background: black;
          margin-top: -4px;
        }
        .whisk-dialog-title {
          position: absolute;
          width: 100%;
          max-width: 551px;
          height: 16px;
          left: 50%;
          transform: translateX(-50%);
          top: 50.05px;
          font-family: 'Google Sans Mono';
          font-style: normal;
          font-weight: 500;
          font-size: 16px;
          line-height: 16px;
          text-align: center;
          text-transform: uppercase;
          color: #000000;
          z-index: 10;
          pointer-events: none;
          overflow: hidden;
          white-space: nowrap;
          text-overflow: ellipsis;
        }
        .whisk-prompt-input::placeholder {
          margin: 0 auto;
          width: 100%;
          max-width: 645px;
          height: 20px;
          font-family: 'Google Sans Text', sans-serif;
          font-style: normal;
          font-weight: 400;
          font-size: 16px;
          line-height: 20px;
          color: #A3A3A3;
          opacity: 1;
          white-space: nowrap;
          overflow: hidden;
          text-overflow: ellipsis;
          text-align: center;
          flex: none;
          order: 0;
          flex-grow: 0;
        }
        @media (max-width: 640px) {
          .whisk-prompt-input::placeholder {
            font-size: 13px;
          }
        }
      `;
      document.head.appendChild(style);
    }
  }, []);

  const activeImageMediaIds = useMemo(() => {
    return (['subject', 'scene', 'style'] as CategoryType[]).flatMap(key => {
      const cat = state[key];
      if (!cat) return [];
      return cat.images.filter(img => img.active && img.mediaId).map(img => img.mediaId!);
    });
  }, [state]);

  const activeCount = useMemo(() => {
    return (['subject', 'scene', 'style'] as CategoryType[]).flatMap(key => {
      const cat = state[key];
      if (!cat) return [];
      return cat.images.filter(img => img.active && img.url);
    }).length;
  }, [state]);

  const isWhiskable = useMemo(() => activeCount > 0 || whiskPrompt.trim().length > 0, [activeCount, whiskPrompt]);

  const handleGenerate = async (type: CategoryType, prompt: string, targetId: string) => {
    setError(null);
    setState(prev => {
      if (!prev[type]) return prev;
      return {
        ...prev,
        [type]: {
          ...prev[type],
          images: prev[type].images.map(img => img.id === targetId ? { ...img, loading: true, prompt } : img)
        }
      };
    });

    try {
      const res = await aiService.generateImage(prompt, '16:9');
      const url = `data:${res.mimeType};base64,${res.base64}`;
      setState(prev => {
        if (!prev[type]) return prev;
        return {
          ...prev,
          [type]: {
            ...prev[type],
            images: prev[type].images.map(img => img.id === targetId ? { 
              ...img, 
              mediaId: res.mediaId, 
              url, 
              loading: false, 
              prompt,
              variants: [{ url, mediaId: res.mediaId, prompt }] 
            } : img)
          }
        };
      });
    } catch (err: any) {
      setError(err.message || 'Generation failed.');
      setState(prev => {
        if (!prev[type]) return prev;
        return {
          ...prev,
          [type]: {
            ...prev[type],
            images: prev[type].images.map(img => img.id === targetId ? { ...img, loading: false } : img)
          }
        };
      });
    }
  };

  const handleSelect = async (type: CategoryType, targetId: string) => {
    setError(null);
    try {
      const media = await Flow.media.select({ filter: 'image' });
      const url = `data:${media.mimeType};base64,${media.base64}`;
      setState(prev => {
        if (!prev[type]) return prev;
        return {
          ...prev,
          [type]: {
            ...prev[type],
            images: prev[type].images.map(img => img.id === targetId ? { 
              ...img, 
              mediaId: media.mediaId, 
              url, 
              prompt: media.name,
              variants: [{ url, mediaId: media.mediaId, prompt: media.name }]
            } : img)
          }
        };
      });
    } catch (err) {
      // User cancelled
    }
  };

  const handleRandomizePlaceholder = async (type: CategoryType, targetId?: string) => {
    setError(null);
    let capturedIndex: number | null = null;
    let finalTargetId: string | null = null;

    setState(prev => {
      const category = prev[type];
      if (!category) return prev;

      const poolSize = POOL_LENGTHS[type];
      let nextIndex = category.currentOrderIndex;
      let order = category.poolOrder;

      if (nextIndex >= poolSize || order.length === 0) {
        order = shuffleIndices(poolSize);
        nextIndex = 0;
      }

      capturedIndex = order[nextIndex];

      const firstEmptyIndex = !targetId ? category.images.findIndex(img => !img.url && !img.loading) : -1;
      const newImages = [...category.images];

      if (targetId) {
        finalTargetId = targetId;
        const idx = newImages.findIndex(img => img.id === targetId);
        if (idx !== -1) newImages[idx] = { ...newImages[idx], loading: true, sourceIndex: capturedIndex };
      } else if (firstEmptyIndex !== -1) {
        finalTargetId = newImages[firstEmptyIndex].id;
        newImages[firstEmptyIndex] = { ...newImages[firstEmptyIndex], loading: true, sourceIndex: capturedIndex };
      } else {
        finalTargetId = Math.random().toString(36).substring(7);
        newImages.push({ id: finalTargetId, active: true, loading: true, sourceIndex: capturedIndex });
      }

      return {
        ...prev,
        [type]: {
          ...category,
          poolOrder: order,
          currentOrderIndex: nextIndex + 1,
          images: newImages
        }
      };
    });

    if (capturedIndex === null) return;

    try {
      const res = await aiService.getLibraryImage(type, capturedIndex);
      const url = `data:${res.mimeType};base64,${res.base64}`;
      setState(prev => {
        if (!prev[type]) return prev;
        return {
          ...prev,
          [type]: { 
            ...prev[type], 
            images: prev[type].images.map(img => img.id === finalTargetId ? { 
              ...img, 
              mediaId: res.mediaId, 
              url, 
              loading: false, 
              prompt: res.prompt, 
              variants: [{ url, mediaId: res.mediaId, prompt: res.prompt }] 
            } : img) 
          }
        };
      });
    } catch (err: any) { 
      setState(prev => {
        if (!prev[type]) return prev;
        return {
          ...prev,
          [type]: {
            ...prev[type],
            images: prev[type].images.map(img => img.id === finalTargetId ? { ...img, loading: false } : img)
          }
        };
      });
    }
  };

  const handleEditImage = async (type: CategoryType, imageId: string) => {
    const image = state[type]?.images.find(img => img.id === imageId);
    if (!image || !image.url) return;
    const existingDescription = image.prompt;
    setInfoModal({ isOpen: true, type, imageId, title: state[type].title, description: existingDescription || null, isLoading: !existingDescription, isGenerating: false });
    if (!existingDescription) {
      try {
        const desc = await aiService.captionImage({ base64: image.url.split(',')[1], mimeType: image.url.split(';')[0].split(':')[1], type });
        setInfoModal(prev => prev ? { ...prev, description: desc, isLoading: false } : null);
        setState(prev => {
          if (!prev[type]) return prev;
          return { ...prev, [type]: { ...prev[type], images: prev[type].images.map(img => img.id === imageId ? { ...img, prompt: desc } : img) } };
        });
      } catch (err) { setInfoModal(null); }
    }
  };

  const handleCompose = async (promptOverride?: string) => {
    const finalPrompt = promptOverride !== undefined ? promptOverride : whiskPrompt;
    if (!isWhiskable && !finalPrompt.trim()) return;

    const ids = [Math.random().toString(36).substring(7), Math.random().toString(36).substring(7)];
    const p = finalPrompt || 'Whisking...';

    setActiveResults(prev => [...ids.map(id => ({ id, loading: true, prompt: p })), ...prev]);

    const gen = async (id: string) => {
      try {
        const res = await aiService.compose({ referenceImageMediaIds: activeImageMediaIds, customPrompt: finalPrompt });
        setActiveResults(prev => prev.map(item => item.id === id ? { 
          ...item, 
          url: `data:${res.mimeType};base64,${res.base64}`, 
          base64: res.base64, 
          mimeType: res.mimeType, 
          loading: false,
          prompt: finalPrompt || 'Whisk Creation'
        } : item));
      } catch (err) { 
        setActiveResults(prev => prev.map(item => item.id === id ? { ...item, loading: false, error: 'Failed' } : item)); 
      }
    };

    ids.forEach(gen);
    if (promptOverride === undefined) setWhiskPrompt('');
  };

  const currentEditedImage = infoModal ? state[infoModal.type]?.images.find(img => img.id === infoModal.imageId) : null;
