/**
 * Core image generation wrapper.
 * Uses Nano Banana 2 as the default for maximum reliability.
 */
const generateImage = async (
  prompt: string, 
  aspectRatio: '16:9' | '1:1' = '16:9', 
  referenceImageMediaIds?: string[]
): Promise<{ base64: string, mimeType: string, mediaId: string }> => {
  try {
    const result = await Flow.generate.image({
      prompt,
      aspectRatio,
      referenceImageMediaIds,
      modelDisplayName: "Nano Banana 2" 
    });

    if (!result || !result.base64) {
      throw new Error("The AI model returned an empty result.");
    }

    return result;
  } catch (error: any) {
    console.error("AI Generation Error:", error);
    throw new Error(error?.message || "The AI is currently processing many requests.");
  }
};

export const aiService = {
  generateImage,

  async getLibraryImage(type: CategoryType, index: number): Promise<{ base64: string, mimeType: string, mediaId: string, prompt: string }> {
    const pools = { subject: CURATED_SUBJECTS, scene: CURATED_SCENES, style: CURATED_STYLES };
    const pool = pools[type];
    const actualIndex = index % pool.length;
    const prompt = pool[actualIndex];
    const res = await generateImage(prompt, '16:9');
    return { ...res, prompt };
  },

  async captionImage(params: { base64: string, mimeType: string, type: CategoryType }): Promise<string> {
    const systemInstruction = `You are an expert image analyst. Describe the ${params.type} in this image with factual detail. Focus on appearance, colors, and textures. Return ONLY the description text.`;
    const userPrompt = `Analyze and describe the ${params.type} in this image for a creative prompt.`;
    try {
      const result = await Flow.generate.text(userPrompt, { 
        systemInstruction, 
        images: [{ base64: params.base64, mimeType: params.mimeType }] 
      });
      return result.text || "No description generated.";
    } catch (err) {
      return "An interesting image choice.";
    }
  },

  async compose(params: { referenceImageMediaIds: string[]; customPrompt?: string }) {
    // If multiple references are provided, we use a prompt that encourages blending.
    const hasReferences = params.referenceImageMediaIds.length > 0;
    const basePrompt = params.customPrompt?.trim() || (hasReferences 
      ? "A masterpiece cinematic blending of the provided reference elements into a cohesive, stunning composition."
      : "A stunning, cinematic landscape masterpiece.");

    // Pass the media IDs to ensure they are used as references
    return await generateImage(basePrompt, '16:9', params.referenceImageMediaIds);
  }
};

