                    <Loader2 className="w-4 h-4 animate-spin" />
                  ) : (
                    <span className="material-symbols-outlined text-[20px]">arrow_forward</span>
                  )}
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { X } from 'lucide-react';

interface ResultViewModalProps {
  isOpen: boolean;
  onClose: () => void;
  result: {
    id: string;
    url: string;
    prompt: string;
  };
  onWhiskAgain: (prompt: string) => void;
}

export const ResultViewModal: React.FC<ResultViewModalProps> = ({ 
  isOpen, 
  onClose, 
  result,
  onWhiskAgain
}) => {
  const [prompt, setPrompt] = useState('');

  useEffect(() => {
    if (isOpen && result) {
      setPrompt(result.prompt);
    }
  }, [isOpen, result]);

  if (!isOpen || !result) return null;

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md">
      <div className="w-full max-w-5xl bg-[#F5D547] rounded-2xl shadow-2xl overflow-hidden relative border border-black/10 flex flex-col h-[85vh] animate-in fade-in zoom-in duration-200">
        <h2 className="whisk-dialog-title">Whisk Result</h2>

        <button 
          onClick={onClose} 
          className="absolute top-6 right-6 p-2 rounded-full hover:bg-black/5 text-black transition-colors z-10"
        >
          <X className="w-6 h-6 text-black" />
        </button>

        <div className="flex-1 flex flex-col overflow-hidden pt-24 pb-8 px-10 gap-8">
          {/* Image Area */}
          <div className="flex-1 min-h-0 rounded-2xl overflow-hidden bg-black/5 border border-black/5 flex items-center justify-center">
            <img 
              src={result.url} 
              alt="Expanded Whisk" 
              className="max-w-full max-h-full object-contain shadow-2xl rounded-lg" 
            />
          </div>

          {/* Controls Area */}
          <div className="flex flex-col gap-6 shrink-0">
             <div className="bg-black/5 rounded-[2rem] p-6 flex flex-col">
                <label className="block text-[10px] font-black uppercase tracking-[0.2em] text-black mb-3">
                  Prompt
                </label>
                <textarea
                  value={prompt}
                  onChange={(e) => setPrompt(e.target.value)}
                  className="w-full bg-transparent border-none text-sm text-black leading-relaxed font-medium focus:ring-0 focus:outline-none resize-none h-20 scrollbar-hide"
                />
              </div>

              <div className="flex items-center justify-center">
                <button
                  type="button"
                  onClick={() => onWhiskAgain(prompt)}
                  className="px-16 py-4 rounded-full bg-black text-white text-[10px] font-black uppercase tracking-[0.2em] hover:bg-zinc-900 transition-all active:scale-95 shadow-xl flex items-center gap-3"
                >
                  <span>Whisk Again</span>
                  <span className="material-symbols-outlined text-[20px]">arrow_forward</span>
                </button>
              </div>
          </div>
        </div>
      </div>
    </div>
  );
};
